69:   const Qt::KeyboardModifiers modifiers = qevent->modifiers();
70: 
71:   this->keyboard->setPosition(PUBLIC(this)->mousepos);
72:   PUBLIC(this)->setModifiers(this->keyboard, qevent);
73: 
