81:     keypadmap->value(qkey, SoKeyboardEvent::ANY) :
82:     keyboardmap->value(qkey, SoKeyboardEvent::ANY);
83: 
84:   //Need to use a temporary to avoid reference becoming deleted before
85:   //we get a hold of it.
86:   QByteArray tmp = qevent->text().toLatin1();
