93:     SbString s;
94:     this->keyboard->enumToString(this->keyboard->getKey(), s);
95:     SoDebugError::postInfo("KeyboardP::keyEvent",
96:                            "enum: '%s', pos: <%i %i>, printable: '%s'",
97:                            s.getString(),
98:                            PUBLIC(this)->mousepos[0],
99:                            PUBLIC(this)->mousepos[1],
100:                            printable);
101:   }
102: #endif
103:   return this->keyboard;
104: }
